// Independent std-only external Ir accounting plus original F61 point/scalar checks.
use std::{collections::{BTreeMap,BTreeSet},fs,path::Path,io::Write};
#[link(name="z")] extern "C" {fn gzopen(p:*const std::ffi::c_char,m:*const std::ffi::c_char)->*mut std::ffi::c_void;fn gzread(f:*mut std::ffi::c_void,b:*mut std::ffi::c_void,n:u32)->i32;fn gzclose(f:*mut std::ffi::c_void)->i32;}
#[link(name="crypto")] extern "C" {fn SHA256(d:*const u8,n:usize,out:*mut u8)->*mut u8;}
fn sha(b:&[u8])->String{let mut out=[0;32];unsafe{assert!(!SHA256(b.as_ptr(),b.len(),out.as_mut_ptr()).is_null());}out.iter().map(|x|format!("{:02x}",x)).collect()}
fn gz(path:&Path)->Vec<u8>{let p=std::ffi::CString::new(path.to_str().unwrap()).unwrap();unsafe{let f=gzopen(p.as_ptr(),c"rb".as_ptr());assert!(!f.is_null());let mut out=vec![];loop{let mut b=[0u8;65536];let n=gzread(f,b.as_mut_ptr().cast(),b.len()as u32);assert!(n>=0);if n==0{break}out.extend_from_slice(&b[..n as usize]);}assert_eq!(gzclose(f),0);out}}
fn md(x:i64)->i64{x.rem_euclid(61)}
fn inv(x:i64)->i64{assert_ne!(md(x),0);let(mut x,mut n,mut r)=(md(x),59,1);while n>0{if n&1==1{r=md(r*x);}x=md(x*x);n>>=1;}r}
type Point=Option<(i64,i64)>;
fn plus(p:Point,q:Point)->Point{let((x,y),(u,v))=match(p,q){(None,q)=>return q,(p,None)=>return p,(Some(p),Some(q))=>(p,q)};if x==u&&md(y+v)==0{return None}let slope=if x==u{md((3*x*x+21)*inv(2*y))}else{md((v-y)*inv(u-x))};let xx=md(slope*slope-x-u);Some((xx,md(slope*(x-xx)-y)))}
fn original(k:i64,x:i64,y:i64){assert!((0..31).contains(&k));assert!((0..61).contains(&x)&&(0..61).contains(&y));assert_eq!(md(y*y),md(x*x*x+21*x+39));let mut p=None;for _ in 0..k{p=plus(p,Some((0,10)));}assert_eq!(p,Some((x,y)),"original point/scalar check");}

fn symbol(line:&str,names:&mut BTreeMap<u64,String>)->Option<u64>{
 let s=line.split_once('=')?.1;let rest=s.strip_prefix('(')?;let(close,after)=rest.split_once(')')?;let id=close.parse().ok()?;let name=after.trim();if !name.is_empty(){if let Some(old)=names.insert(id,name.to_string()){assert_eq!(old,name,"symbol identity changed");}}Some(id)
}
fn counter(text:&str,label:&str,method:i64,names:&mut BTreeMap<u64,String>)->u64{
 assert!(text.lines().any(|l|l=="events: Ir"));assert!(text.lines().any(|l|l.starts_with("desc:")&&l.contains(label)));let positions=text.lines().find_map(|l|l.strip_prefix("positions:")).unwrap().split_whitespace().collect::<Vec<_>>();assert!(positions.is_empty()||positions==["line"]);let np=positions.len();
 let(mut summary,mut totals,mut sum,mut skip,mut current,mut cold_cost)=(None,None,0u64,false,None,0u64);
 for line in text.lines(){
  if line.starts_with("fn="){current=symbol(line,names);continue;}if line.starts_with("cfn="){symbol(line,names);continue;}
  if let Some(v)=line.strip_prefix("summary:"){assert!(summary.replace(v.trim().parse::<u64>().unwrap()).is_none());continue;}
  if let Some(v)=line.strip_prefix("totals:"){assert!(totals.replace(v.trim().parse::<u64>().unwrap()).is_none());continue;}
  if line.starts_with("calls="){assert!(!skip);skip=true;continue;}
  let words=line.split_whitespace().collect::<Vec<_>>();if words.len()!=np+1{continue;}if np==1&&!(words[0]=="*"||words[0].starts_with("0x")||words[0].parse::<i64>().is_ok()){continue;}
  let Ok(value)=words[np].parse::<u64>()else{continue;};if skip{skip=false;continue;}sum=sum.checked_add(value).unwrap();if let Some(id)=current{let name=names.get(&id).unwrap();let expected=if method==0{"Legacy::recover_cold"}else{"RootCover::recover_cold"};if name.contains(expected){cold_cost=cold_cost.checked_add(value).unwrap();}}
 }
 assert!(!skip);let summary=summary.unwrap();assert_eq!(summary,sum,"external summary versus independent function SELF sum");assert_eq!(totals.unwrap(),sum);assert!(sum>0&&cold_cost>0,"actual measured method body must have positive self cost");summary
}
fn numbers(words:&[&str])->Vec<i64>{words.iter().map(|x|x.parse().unwrap()).collect()}
fn audit(cases:&Path,refs:&Path,head:&str)->String{
 let references=String::from_utf8(gz(refs)).unwrap();let mut rows=BTreeMap::new();let mut lines=references.lines();assert_eq!(lines.next().unwrap(),"S twist.counter-reference.first-row.v1");
 for line in lines{let w=line.split_whitespace().collect::<Vec<_>>();assert_eq!(w.len(),26);assert_eq!(w[0],"E");let n=numbers(&w[1..]);let key=(n[0],n[1],n[2],n[3]);assert!(rows.insert(key,n[4..].to_vec()).is_none());}assert_eq!(rows.len(),81900);
 let input=gz(cases);let text=String::from_utf8(input.clone()).unwrap();let mut input_lines=text.lines();let header=input_lines.next().unwrap().split_whitespace().collect::<Vec<_>>();assert_eq!(header.len(),9);assert_eq!(&header[..5],["S","twist.policy-counter.v1","61","59","31"]);assert_eq!(header[8],head);assert!(head.len()==40&&head.bytes().all(|x|x.is_ascii_hexdigit()));let tag=header[5];assert!(tag=="A"||tag=="B");let first:i64=header[6].parse().unwrap();let end:i64=header[7].parse().unwrap();assert!(0<=first&&first<end&&end<=455);
 let warm_text=String::from_utf8(gz(&cases.parent().unwrap().join("warmups.tsv.gz"))).unwrap();let mut warm_lines=warm_text.lines();assert_eq!(warm_lines.next().unwrap(),format!("S twist.policy-warmup.v1 {} {} {}",tag,first,head));
 for route in 3..6{for method in 0..2{for rep in 0..2{assert_eq!(warm_lines.next().unwrap(),format!("W {} {} {} warmup-{}",method,route,first,rep));for qi in 1..31{let w=warm_lines.next().unwrap().split_whitespace().collect::<Vec<_>>();assert_eq!(w.len(),23);assert_eq!(w[0],"R");assert_eq!(w[1].parse::<i64>().unwrap(),qi);let result=numbers(&w[2..]);assert_eq!(&result,rows.get(&(method,route,first,qi)).unwrap());original(result[2],result[0],result[1]);}}}}assert!(warm_lines.next().is_none());

 let mut expected=vec![];if tag=="A"{for p in first..end{for r in 3..6{for m in 0..2{expected.push((m,r,p,"plain"));}}}}else{for p in(first..end).rev(){for r in(3..6).rev(){for m in(0..2).rev(){expected.push((m,r,p,"plain"));}}}}
 expected.extend([(0,3,first,"repeat-aa"),(0,3,first,"positive-inside"),(0,3,first,"negative-outside")]);let dir=cases.parent().unwrap();let(mut symbols,mut output,mut seen,mut raw_total,mut compressed_total)=(BTreeMap::new(),vec![],BTreeSet::new(),0u64,0u64);let mut all_counts=vec![];
 for(index,(method,route,policy,label))in expected.iter().enumerate(){let line=input_lines.next().expect("missing policy/method interval");let w=line.split_whitespace().collect::<Vec<_>>();assert_eq!(w.len(),13);assert_eq!(w[0],"P");assert_eq!(w[1].parse::<usize>().unwrap(),index+1);assert_eq!(w[2].parse::<i64>().unwrap(),*method);assert_eq!(w[3].parse::<i64>().unwrap(),*route);assert_eq!(w[4].parse::<i64>().unwrap(),*policy);assert_eq!(w[5].parse::<i64>().unwrap(),3);assert_eq!(w[6],*label);assert!(Path::new(w[7]).components().count()==1&&w[7].ends_with(".raw.gz"));assert!(seen.insert(w[7]));let path=dir.join(w[7]);let compressed=fs::read(&path).unwrap();assert_eq!(sha(&compressed),w[10]);assert_eq!(compressed.len()as u64,w[11].parse::<u64>().unwrap());let raw=gz(&path);assert_eq!(sha(&raw),w[8]);assert_eq!(raw.len()as u64,w[9].parse::<u64>().unwrap());let raw_text=String::from_utf8(raw).unwrap();let unique=format!("{}-{}-{}-m{}-r{}-p{}-d{}-n30",tag,head,label,method,route,policy,3);let cost=counter(&raw_text,&unique,*method,&mut symbols);assert_eq!(cost,w[12].parse::<u64>().unwrap(),"recorded external cost");raw_total+=w[9].parse::<u64>().unwrap();compressed_total+=w[11].parse::<u64>().unwrap();
  for qi in 1..31{let w=input_lines.next().expect("missing original target").split_whitespace().collect::<Vec<_>>();assert_eq!(w.len(),23);assert_eq!(w[0],"R");assert_eq!(w[1].parse::<i64>().unwrap(),qi);let result=numbers(&w[2..]);assert_eq!(&result,rows.get(&(*method,*route,*policy,qi)).unwrap(),"complete independently replayed source result binding");original(result[2],result[0],result[1]);}
  all_counts.push(cost);output.push(format!("{{\"method\":{},\"route\":{},\"policy\":{},\"label\":\"{}\",\"instruction_reads\":{},\"original_scalars_checked\":30,\"raw_bytes\":{},\"gzip_bytes\":{}}}",method,route,policy,label,cost,w[9],w[11]));
 }
 assert!(input_lines.next().is_none(),"extra policy/target rows");let base=expected.iter().position(|x|*x==(0,3,first,"plain")).unwrap();let n=all_counts.len();let aa=all_counts[base].abs_diff(all_counts[n-3]);assert!(all_counts[n-2]>all_counts[base].max(all_counts[n-3]).max(all_counts[n-1])+10000,"inside positive not detected");assert!(all_counts[n-1].abs_diff(all_counts[n-3])<=aa.max(1000),"outside negative exceeds frozen AA tolerance");
 format!("{{\"schema\":\"twist.policy-counter-audit.v1\",\"stream\":\"{}\",\"head\":\"{}\",\"first_policy\":{},\"end_policy\":{},\"intervals\":{},\"warmup_workloads\":360,\"actual_source_workloads_including_controls\":{},\"raw_bytes\":{},\"gzip_bytes\":{},\"aa_instruction_difference\":{},\"positive_detected\":true,\"negative_within_tolerance\":true,\"records\":[{}],\"speed_claim\":false,\"signed_verdict\":false}}\n",tag,head,first,end,expected.len(),expected.len()*30,raw_total,compressed_total,aa,output.join(","))
}
fn main(){let args=std::env::args().collect::<Vec<_>>();if args.len()!=6{std::process::exit(2)}let result=std::panic::catch_unwind(||{assert_eq!(sha(&fs::read(&args[2]).unwrap()),args[5],"actual immutable mathematical reference bytes");let receipt=audit(Path::new(&args[1]),Path::new(&args[2]),&args[3]);fs::OpenOptions::new().write(true).create_new(true).open(&args[4]).unwrap().write_all(receipt.as_bytes()).unwrap();});if result.is_err(){std::process::exit(101)}}
